package admin

import "errors"

func fmtURL() error { return errors.New("invalid backend URL") }

const page = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Raptor Admin</title>
<style>
:root{font:15px/1.5 "Avenir Next",Avenir,"Segoe UI",sans-serif;color:#203243;background:#edf2f3;--ink:#102c3d;--teal:#087a75;--line:#d4dfe2;--muted:#617682}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #e8ae50;outline-offset:2px}[hidden]{display:none!important}.shell{min-height:100vh;display:grid;grid-template-columns:240px minmax(0,1fr)}aside{background:var(--ink);color:#e8f1f1;padding:30px 22px;display:flex;flex-direction:column;gap:32px}.brand{font-size:27px;font-weight:800;letter-spacing:-1.5px;line-height:1}.brand span{color:#65c5b9}.brand small{display:block;margin-top:12px;font-size:11px;font-weight:600;letter-spacing:.05em;color:#a9c1c9}.rail-label{font-size:12px;color:#9eb9c3;margin:0 0 10px}.rail-link{display:block;padding:10px 12px;border-radius:7px;color:#e4f0f0;text-decoration:none;margin:2px 0}.rail-link:hover,.rail-link:focus-visible{background:#24495a}.rail-foot{margin-top:auto;font-size:12px;color:#a9c1c9;line-height:1.6}main{min-width:0;padding:38px clamp(20px,5vw,76px) 80px;max-width:1440px;width:100%;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:end;gap:20px;border-bottom:2px solid var(--ink);padding-bottom:22px;margin-bottom:28px}.page-head h1{font-size:clamp(31px,4vw,48px);line-height:1.05;letter-spacing:-.055em;color:var(--ink);margin:0}.page-head p{margin:9px 0 0;color:var(--muted);max-width:52ch}.section{background:#fff;border:1px solid var(--line);border-radius:10px;margin:0 0 20px;padding:26px}.section h2{font-size:21px;letter-spacing:-.03em;color:var(--ink);margin:0 0 4px}.section-desc{color:var(--muted);font-size:13px;margin:0 0 21px}.section-head{display:flex;justify-content:space-between;gap:14px;align-items:start;margin-bottom:18px}.section-head .section-desc{margin-bottom:0}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.grid.two{grid-template-columns:repeat(2,minmax(0,1fr))}.field{display:block;font-weight:650;font-size:13px;color:#37505e}.field input,.field select,.field textarea{display:block;width:100%;margin-top:7px}.field input,.field select,.field textarea{border:1px solid #b9cbd0;border-radius:6px;background:#fff;color:var(--ink);padding:10px 12px;min-height:43px}.field textarea{resize:vertical;min-height:140px;font:13px/1.5 ui-monospace,SFMono-Regular,monospace}.wide{grid-column:1/-1}.actions{display:flex;gap:10px;align-items:center;margin-top:16px;flex-wrap:wrap}.button{border:1px solid var(--teal);background:var(--teal);color:white;border-radius:6px;padding:10px 16px;font-weight:700}.button:hover{background:#086762}.button.secondary{background:white;color:var(--ink);border-color:#9db3bc}.button.secondary:hover{background:#edf4f4}.check{display:flex;gap:9px;align-items:center;font-size:13px}.check input{accent-color:var(--teal);width:17px;height:17px}.record-list{list-style:none;margin:0;padding:0;border-top:1px solid var(--line)}.record-list li{display:flex;justify-content:space-between;gap:12px;padding:12px 2px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.record-list li:before{content:"";height:8px;width:8px;flex:none;background:#42a895;border-radius:50%;margin:7px 7px 0 2px}.record-list li{justify-content:start}.record-list li .role{margin-left:auto;color:var(--muted)}.empty{color:var(--muted);font-size:13px;margin:0}.data-list{display:grid;gap:8px}.data-row{border:1px solid var(--line);border-left:3px solid var(--teal);border-radius:5px;padding:11px 13px;background:#fbfdfd;display:grid;grid-template-columns:minmax(130px,1fr) 2fr;gap:10px;overflow-wrap:anywhere}.data-row strong{color:var(--ink)}.data-row span{font-size:13px;color:var(--muted)}#notice{padding:12px 16px;border-radius:6px;margin:0 0 20px;background:#fff4dc;border:1px solid #e8c57b;color:#724619}#notice:empty{display:none}.sign-in{max-width:650px}.sign-in form{display:grid;gap:13px}.sign-in .button{justify-self:start}.muted{color:var(--muted)}@media(max-width:850px){.shell{grid-template-columns:1fr}aside{padding:18px 22px;gap:0}.brand{font-size:23px}.brand small,.rail-foot,.rail-label{display:none}aside nav{display:flex;gap:5px;margin-top:12px}.rail-link{font-size:13px;padding:6px 9px}main{padding:24px 18px 48px}}@media(max-width:650px){.grid,.grid.two{grid-template-columns:1fr}.section{padding:20px}.page-head{align-items:start}.data-row{grid-template-columns:1fr;gap:2px}}
.repo-rows{display:grid;gap:12px}.repo-rows fieldset{border:1px solid var(--line);border-radius:7px;padding:16px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.repo-rows legend{color:var(--ink);font-weight:700;padding:0 5px}.repo-rows .button{justify-self:start;align-self:end}@media(max-width:650px){.repo-rows fieldset{grid-template-columns:1fr}}#model-admin>section{background:#fff;border:1px solid var(--line);border-radius:10px;margin:0 0 20px;padding:26px}#model-admin h2{font-size:21px;letter-spacing:-.03em;color:var(--ink);margin:0 0 16px}#model-admin button{border:1px solid var(--teal);background:var(--teal);color:#fff;border-radius:6px;padding:10px 16px;font-weight:700;margin:0 10px 10px 0}#model-admin button:hover{background:#086762}#model-admin button:disabled{opacity:.5;cursor:not-allowed}#model-admin form{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}#model-admin form label{display:inline-flex;align-items:center;gap:5px;margin:5px 0}#model-admin select{border:1px solid #b9cbd0;border-radius:6px;padding:8px;margin:8px}#model-admin input[type=checkbox]{accent-color:var(--teal)}#model-admin a{color:var(--teal)}@media(max-width:650px){#model-admin>section{padding:20px}}</style></head><body><div class="shell"><aside><div class="brand">Raptor<span>.</span><small>Administration</small></div><nav aria-label="Admin sections"><p class="rail-label">Workspace</p><a class="rail-link" href="#users-section">Users</a><a class="rail-link" href="#groups-section">Environment groups</a><a class="rail-link" href="#environments-section">Environments</a><a class="rail-link" href="#model-admin">AI models</a></nav><div class="rail-foot">Platform access and environment configuration</div></aside><main><header class="page-head"><div><h1>Administration</h1><p>Manage who can access Raptor and how deployment environments are organized.</p></div><button class="button secondary" id="logout" hidden>Sign out</button></header><p id="notice" role="alert"></p><section class="section sign-in" id="sign-in-section"><h2>Sign in</h2><p class="section-desc">Use your administrator account to manage this workspace.</p><form id="login"><label class="field">Username<input name="username" required autocomplete="username"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password"></label><button class="button">Sign in</button></form></section><div id="management" hidden><section class="section" id="users-section"><div class="section-head"><div><h2>Users</h2><p class="section-desc">Create accounts and assign their access level.</p></div></div><form id="create"><div class="grid"><label class="field">Username<input name="username" required autocomplete="off"></label><label class="field">Password<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label class="field">Role<select name="role"><option value="user">User</option><option value="admin">Admin</option></select></label></div><div class="actions"><button class="button">Create user</button></div></form><h3>Existing users</h3><ul id="users" class="record-list"></ul></section><div id="environment-admin"></div></div></main></div><script>
let csrf;async function api(path,method='GET',body){const r=await fetch('/api/v1/'+path,{method,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const v=await r.json();if(!r.ok)throw Error(v.error?.code||'Unavailable');return v.data}
async function refresh(){const s=await api('session');csrf=s.csrf;if(s.user.role!=='admin')throw Error('Administrator access required');document.getElementById('management').hidden=false;document.getElementById('sign-in-section').hidden=true;document.getElementById('logout').hidden=false;const users=await api('users');const ul=document.getElementById('users');ul.replaceChildren();for(const u of users){const li=document.createElement('li');const name=document.createElement('strong');name.textContent=u.username;const role=document.createElement('span');role.className='role';role.textContent=u.role;li.append(name,role);ul.append(li)}if(!users.length){const li=document.createElement('li');li.textContent='No users yet.';ul.append(li)}}
function safely(f){return async e=>{e.preventDefault();try{document.getElementById('notice').textContent='';await f(e)}catch(x){document.getElementById('notice').textContent=x.message}}}
document.getElementById('login').onsubmit=safely(async e=>{const d=Object.fromEntries(new FormData(e.target));const s=await api('login','POST',d);csrf=s.csrf;e.target.reset();await refresh()});
document.getElementById('create').onsubmit=safely(async e=>{await api('users','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await refresh();document.getElementById('notice').textContent='User created.'});
document.getElementById('logout').onclick=safely(async()=>{await api('logout','POST',{});document.getElementById('management').hidden=true;document.getElementById('sign-in-section').hidden=false;document.getElementById('logout').hidden=true;csrf=undefined});refresh().catch(()=>{});
</script></body></html>`
